<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor\TemplateVariableValueAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateVariableValueAccessor trait.
 *
 * Covers null default, string/VO assignment via withValue,
 * getValue/value accessors, and isValueChanged with/without original.
 */
class TemplateVariableValueAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withValue creates a new instance with the Value set
     * from a string value, and getValue returns the primitive string.
     */
    public function testWithValueFromString(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVariableValueAccessorUnitTest();

        // Act
        $result = $holder->withValue('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getValue());
    }
    /**
     * Asserts that withvalue has access to the value object
     * from a string value, and getValue returns the primitive string.
     */
    public function testWithValueFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVariableValueAccessorUnitTest();

        // Act
        $result = $holder->withValue('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->value()->value());
    }
    public function testChangedValue(): void
    {
        // Arrange
        $holder = new ImplWithTemplateVariableValueAccessorUnitTest();
        $original = $holder->withValue('one');
        $same = $holder->withValue('one');
        $modified = $holder->withValue('other');

        // Act
        $unchanged = $holder->isValueChanged();
        $withSame = $original->isValueChanged($same);
        $withDiferent = $original->isValueChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTemplateVariableValueAccessorUnitTest
{
    use TemplateVariableValueAccessor;
}
